// Builds the icon package from the set maps and the SVG sources.
//
//   npx tsx packages/icons/build.ts          writes the generated files
//   npx tsx packages/icons/build.ts --check  exits 1 when a file is out of date
//
// Output (committed, deterministic):
//   src/generated/<set>.gen.ts   name to { viewBox, body } for every system name
//   src/generated/sets.gen.ts    the set registry
//   Angular and react-native-svg components from templates/. They land in
//   src/angular and src/native once their framework is installed, and in
//   generated-pending/ until then, so the root typecheck stays green.
//
// A new icon set is one file in sets/ plus one line in `sources` below.
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { pathToFileURL } from 'node:url';
import { iconNames } from './src/names';
import type { IconStyle } from './src/types';
import line from './sets/line';
import pixel from './sets/pixel';
import type { IconSetSource } from './sets/source';

export const sources: readonly IconSetSource[] = [pixel, line];

const here = import.meta.dirname;
const repoRoot = join(here, '..', '..');
const header = '// Generated by packages/icons/build.ts. Do not edit.\n';
const allowedTags = new Set(['path', 'circle', 'rect', 'line', 'polyline', 'polygon', 'ellipse']);
// Attributes that carry no drawing.
const droppedAttrs = new Set(['class', 'id']);

interface Glyph {
  viewBox: string;
  body: string;
}

function packageDir(pkg: string): string {
  let dir = here;
  for (;;) {
    const candidate = join(dir, 'node_modules', pkg);
    if (existsSync(candidate)) return candidate;
    const parent = dirname(dir);
    if (parent === dir) throw new Error(`package ${pkg} is not installed`);
    dir = parent;
  }
}

function hasPackage(pkg: string): boolean {
  try {
    packageDir(pkg);
    return true;
  } catch {
    return false;
  }
}

/** Minimal SVG optimizer: keeps the viewBox and flat drawing elements, drops everything else. */
export function optimizeSvg(svg: string, file = 'svg'): Glyph {
  const clean = svg.replace(/<!--[\s\S]*?-->/g, '').replace(/<\?xml[\s\S]*?\?>/g, '');
  const root = /<svg\b([^>]*)>([\s\S]*)<\/svg>/.exec(clean);
  if (!root) throw new Error(`${file}: no svg root`);
  const viewBox = /\bviewBox="([^"]+)"/.exec(root[1] ?? '')?.[1]?.trim().replace(/\s+/g, ' ');
  if (!viewBox) throw new Error(`${file}: no viewBox`);
  const inner = (root[2] ?? '').trim();
  const parts: string[] = [];
  const element = /<([a-zA-Z]+)\b([^>]*?)\s*\/>/g;
  for (const m of inner.matchAll(element)) {
    const tag = m[1] as string;
    if (!allowedTags.has(tag)) throw new Error(`${file}: element <${tag}> is not supported`);
    const attrs: string[] = [];
    for (const a of (m[2] ?? '').matchAll(/([a-zA-Z:-]+)="([^"]*)"/g)) {
      const name = a[1] as string;
      if (droppedAttrs.has(name)) continue;
      attrs.push(`${name}="${(a[2] as string).trim().replace(/\s+/g, ' ')}"`);
    }
    parts.push(`<${tag}${attrs.map((x) => ` ${x}`).join('')}/>`);
  }
  // Anything left that is not whitespace is markup the parser did not take, for example a group.
  const rest = inner.replace(element, '').trim();
  if (rest !== '') throw new Error(`${file}: unsupported markup ${rest.slice(0, 40)}`);
  if (parts.length === 0) throw new Error(`${file}: no drawing elements`);
  return { viewBox, body: parts.join('') };
}

export function readGlyph(source: IconSetSource, glyph: string): Glyph {
  const file = join(packageDir(source.package), source.dir, `${glyph}.svg`);
  if (!existsSync(file)) throw new Error(`${source.id}: glyph ${glyph} not found in ${source.package}`);
  return optimizeSvg(readFileSync(file, 'utf8'), `${source.package}/${glyph}.svg`);
}

/** Every style's icons.ts: the set it uses and the glyphs its map points at. */
export async function styleMaps(): Promise<{ style: string; config: IconStyle }[]> {
  const stylesDir = join(repoRoot, 'packages', 'styles');
  const out: { style: string; config: IconStyle }[] = [];
  if (!existsSync(stylesDir)) return out;
  for (const style of readdirSync(stylesDir).sort()) {
    const file = join(stylesDir, style, 'icons.ts');
    if (!existsSync(file)) continue;
    const mod = (await import(pathToFileURL(file).href)) as { default: IconStyle };
    out.push({ style, config: mod.default });
  }
  return out;
}

function q(value: string): string {
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

function key(name: string): string {
  return /^[a-zA-Z_$][\w$]*$/.test(name) ? name : q(name);
}

function setModule(source: IconSetSource, extra: readonly string[]): string {
  const lines = [header, `import type { IconSetData } from '../types';`, ''];
  lines.push(`// ${source.package} (${source.license}).`);
  lines.push(`export const ${source.id}: IconSetData = {`);
  lines.push(`  id: ${q(source.id)},`);
  lines.push(`  attrs: { ${Object.entries(source.attrs).map(([k, v]) => `${key(k)}: ${q(v)}`).join(', ')} },`);
  lines.push('  icons: {');
  for (const name of iconNames) {
    const g = readGlyph(source, source.glyphs[name]);
    lines.push(`    ${key(name)}: { viewBox: ${q(g.viewBox)}, body: ${q(g.body)} },`);
  }
  lines.push('  },');
  lines.push('  glyphs: {');
  for (const glyph of extra) {
    const g = readGlyph(source, glyph);
    lines.push(`    ${key(glyph)}: { viewBox: ${q(g.viewBox)}, body: ${q(g.body)} },`);
  }
  lines.push('  },');
  lines.push('};');
  return lines.join('\n') + '\n';
}

function registryModule(): string {
  const ids = sources.map((s) => s.id);
  return [
    header,
    ...ids.map((id) => `import { ${id} } from './${id}.gen';`),
    '',
    `export const iconSets = { ${ids.join(', ')} } as const;`,
    '',
    'export type IconSetId = keyof typeof iconSets;',
    '',
    `export const iconSetIds: readonly IconSetId[] = [${ids.map(q).join(', ')}];`,
    '',
  ].join('\n');
}

interface FrameworkTarget {
  name: string;
  /** Packages the emitted files import. When one is missing the files go to generated-pending. */
  needs: string[];
  files: Record<string, string>;
}

const frameworks: FrameworkTarget[] = [
  {
    name: 'angular',
    needs: ['@angular/core'],
    files: { 'icon.ts': 'icon.ts.tpl', 'index.ts': 'index.ts.tpl' },
  },
  {
    name: 'native',
    needs: ['react-native', 'react-native-svg'],
    files: { 'Icon.tsx': 'Icon.tsx.tpl', 'index.ts': 'index.ts.tpl' },
  },
];

export function frameworkDir(fw: FrameworkTarget, ready = fw.needs.every(hasPackage)): string {
  return ready ? join(here, 'src', fw.name) : join(here, 'generated-pending', fw.name);
}

/** Every generated file, path to content. Pure apart from reading the sources. */
export async function generate(): Promise<Map<string, string>> {
  const out = new Map<string, string>();
  const maps = await styleMaps();
  const ids = new Set(sources.map((s) => s.id));
  for (const { style, config } of maps) {
    if (!ids.has(config.set)) throw new Error(`styles/${style}/icons.ts names unknown set ${config.set}`);
  }
  for (const source of sources) {
    const extra = new Set<string>();
    for (const { config } of maps) {
      if (config.set !== source.id) continue;
      for (const glyph of Object.values(config.map ?? {})) if (glyph !== undefined) extra.add(glyph);
    }
    out.set(join(here, 'src', 'generated', `${source.id}.gen.ts`), setModule(source, [...extra].sort()));
  }
  out.set(join(here, 'src', 'generated', 'sets.gen.ts'), registryModule());
  for (const fw of frameworks) {
    const dir = frameworkDir(fw);
    for (const [target, template] of Object.entries(fw.files)) {
      const body = readFileSync(join(here, 'templates', fw.name, template), 'utf8');
      out.set(join(dir, target), header + body);
    }
  }
  return out;
}

export async function build(check = false): Promise<string[]> {
  const files = await generate();
  const stale: string[] = [];
  for (const [path, content] of files) {
    if (existsSync(path) && readFileSync(path, 'utf8') === content) continue;
    stale.push(relative(repoRoot, path));
    if (check) continue;
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
  }
  // A framework emits to one place only. Remove what the other place holds.
  if (!check) {
    for (const fw of frameworks) {
      const ready = fw.needs.every(hasPackage);
      const other = frameworkDir(fw, !ready);
      for (const target of Object.keys(fw.files)) rmSync(join(other, target), { force: true });
    }
  }
  return stale;
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const check = process.argv.includes('--check');
  const stale = await build(check);
  for (const f of stale) console.log(`${check ? 'out of date' : 'wrote'} ${f}`);
  if (check && stale.length > 0) process.exit(1);
  console.log(`icons: ${iconNames.length} names, ${sources.length} sets`);
}
